const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function pavingPicture(n,patches,prefix='paving-live'){
 const side=n+1,step=240/side,total=n*n+n*Number(patches.row)+n*Number(patches.column)+Number(patches.corner),added=total-n*n;
 const label=`Old square: ${n} rows of ${n}, ${n*n} old tiles. Bottom patch: ${patches.row?n:0}. Right patch: ${patches.column?n:0}. Corner: ${patches.corner?1:0}. ${added} added, ${total} tiles now. Missing positions are outlines, not tiles.`;
 let cells='';for(let r=0;r<side;r++)for(let c=0;c<side;c++){
  const part=r<n&&c<n?'old':r===n&&c<n?'row':c===n&&r<n?'column':'corner',filled=part==='old'||patches[part],x=32+c*step,y=30+r*step;
  cells+=`<rect data-paving-slot="${r}-${c}" data-paving-part="${part}" data-filled="${filled}" ${filled?`data-paving-tile="${part}-${r}-${c}"`:''} x="${x}" y="${y}" width="${step-3}" height="${step-3}" rx="${Math.min(4,step/9)}" fill="${filled?`url(#${prefix}-${part})`:'#fffdf5'}" stroke="${filled?'#536a59':part==='corner'?'#a65a68':'#a4afa2'}" stroke-width="1.1" ${filled?'':'stroke-dasharray="3 3"'}/>`;
 }
 return `<svg class="paving-picture" viewBox="0 0 304 292" role="img" aria-label="${esc(label)}" data-paving-n="${n}"><defs><pattern id="${prefix}-old" width="10" height="10" patternUnits="userSpaceOnUse"><rect width="10" height="10" fill="#dce8d4"/><circle cx="5" cy="5" r="1.3" fill="#658467"/></pattern><pattern id="${prefix}-row" width="8" height="8" patternUnits="userSpaceOnUse"><rect width="8" height="8" fill="#f5dfae"/><path d="M0 4H8" stroke="#9d752f"/></pattern><pattern id="${prefix}-column" width="9" height="9" patternUnits="userSpaceOnUse"><rect width="9" height="9" fill="#d6e9e7"/><path d="M-2 2L2-2M0 9L9 0M7 11L11 7" stroke="#4a7e83"/></pattern><pattern id="${prefix}-corner" width="10" height="10" patternUnits="userSpaceOnUse"><rect width="10" height="10" fill="#f0d8d8"/><path d="M5 2V8M2 5H8" stroke="#a65a68"/></pattern></defs><g aria-hidden="true">${cells}<path data-paving-old-outline d="M30 28H${32+n*step-1}V${30+n*step-1}H30Z" fill="none" stroke="#355b40" stroke-width="2"/></g></svg>`;
}
export const pavingLegend=()=>'<div class="paving-legend" aria-label="Tile key"><span><i class="paving-key-old"></i>Old tiles</span><span><i class="paving-key-row"></i>Bottom patch</span><span><i class="paving-key-column"></i>Right patch</span><span><i class="paving-key-corner"></i>One corner</span></div>';
